import json
from pathlib import Path
out=Path('docs/product/presentation')
slides=[]
def slide(id,title,layout,seconds,notes,**kw):
    slides.append(dict(id=id,title=title,layout=layout,seconds=seconds,appendix=id>12,notes=notes,**kw))
slide(1,'Dearby','cover',20,'Dearby는 IT·개발에 관심 있는 대학생이 흩어진 교외 활동 중 자신의 방향과 원하는 경험에 맞는 프로그램을 찾도록 돕는 앱입니다. 이번 발표는 사용자와 합의한 재기획 방향을 설명합니다. 자동 수집과 개인화 추천을 이미 완성했다는 의미는 아닙니다.',subtitle='원하는 직무와 경험으로\n교외 활동을 찾는 앱',caption='제품 재기획 · 학교 프로젝트 발표',image='assets/collaboration-concept.png',status='기획 합의',sources=['../replanning-2026-09.md'])
slide(2,'활동을 찾는 데 드는 수고','statement',35,'기획자의 실제 탐색 경험에서 출발했습니다. 지인이나 광고, 구글 검색, 공고사이트를 통해 활동을 접했지만 개별 단체 페이지에만 소개된 활동도 있었습니다. 이 관찰을 모든 대학생의 조사 결과로 일반화하지 않습니다. Dearby가 우선 줄이려는 것은 여러 사이트를 뒤지는 시간과 수고입니다.',headline='여러 곳을 찾아보고,\n나에게 맞는지 다시 읽는다',items=[['흩어진 발견 경로','지인·SNS 광고·검색·공고사이트'],['다시 확인해야 하는 정보','직무, 제공 경험, 지원 자격, 모집 시기']],footnote='기획자의 탐색 경험에서 출발한 문제 정의 · 사용자 조사로 추가 검증 필요',status='문제 가설',sources=['../replanning-2026-09.md'])
slide(3,'첫 사용자와 제공 범위','split',30,'첫 버전은 IT·개발에 관심 있는 대학생의 교외 활동 탐색에 집중합니다. 학과를 바탕으로 관련 직무를 제안하되 학과와 무관한 선택도 열어둡니다. 향후 분야와 대상을 넓힐 수 있지만, 기존에 논의했던 Q&A나 크레딧은 이번 핵심 범위에서 제외했습니다.',columns=[{'title':'먼저 집중할 대상','lines':['IT·개발에 관심 있는 대학생','교외 활동 중심의 프로그램 탐색','학과 기반 직무 제안 + 자유 선택']},{'title':'핵심 제공 가치','lines':['흩어진 활동을 모아 탐색','원하는 경험으로 비교','지원 조건을 확인하고 저장']}],footnote='이번 핵심 범위: 활동 발견과 참여 검토 · Q&A·커피챗·크레딧 제외',status='기획 합의',sources=['../replanning-2026-09.md'])
slide(4,'사용자가 정하는 맞춤 기준','sequence',35,'프로필은 나아갈 방향과 지금 필요한 경험을 나눠 묻습니다. 경험은 네트워킹 같은 행위만 선택하거나, 현직자와의 네트워킹처럼 세부 조건까지 고를 수 있습니다. 이 묶음 중 하나를 가장 원하는 경험으로 지정합니다. 구체 입력 화면과 선택 수는 아직 정하지 않았습니다.',steps=[['나아갈 방향','백엔드 · 프론트엔드 · 디자인 등'],['지금 필요한 경험','제작 → 앱 → 팀협업'],['가장 원하는 경험','선택한 경험 묶음 중 최우선 지정']],footnote='세부 조건은 선택 사항 · 학과가 직무 선택을 제한하지 않음',status='기획 합의',sources=['../action-based-experience-tags-draft.md','../tag-types-and-profile-draft.md'])
slide(5,'경험을 행위와 속성으로 표현','table',45,'사회성이나 성장처럼 넓은 말만 쓰면 실제로 무엇을 하는지 알기 어렵습니다. 그래서 네트워킹은 누구와, 제작은 무엇을 어떻게 하는지로 구체화합니다. 과제수행은 주어진 문제나 요구사항을 직접 수행하는 경험이고, 청강은 설명이나 강연을 듣는 활동입니다. 모든 활동에 같은 속성을 강제하지 않으며 이 표의 값은 전체 사전이 아닌 예시입니다.',headers=['행위','세부 질문','표현 예시'],rows=[['네트워킹','누구와','네트워킹 | 현직자, 동료'],['제작','무엇을 · 어떻게','제작 | 앱 · 팀협업'],['과제수행','무엇을','과제수행 | 서비스 기획'],['청강','무엇을','청강 | 개발 업무 소개']],footnote='행위별로 필요한 속성만 사용 · 원문 근거가 있는 경험만 부여',status='구조 합의 · 값은 예시',sources=['../action-based-experience-tags-draft.md'])
slide(6,'탐색의 단위는 프로그램','split',35,'같은 프로그램이 여러 기수나 직무로 공고를 올려도 기본 탐색에서는 프로그램 하나를 카드 하나로 보여줍니다. 상세에서 회차와 직무별 모집 정보를 확인하고, 스크랩도 조직이나 프로그램을 대상으로 합니다. 결과 개수는 공고 수가 아니라 중복 없는 프로그램 수입니다. 다른 직무가 모집 중이어도 내가 고른 직무가 마감됐다면 구분해서 표시합니다.',columns=[{'title':'프로그램 카드','lines':['프로그램 하나당 카드 하나','경험과 선택 직무의 모집 상태','조직·프로그램 스크랩']},{'title':'프로그램 상세','lines':['회차·직무별 공고 확인','해당 회차의 자격·일정·근거','과거 경험은 기수를 구분해 표시']}],footnote='필터 결과 수 = 중복 없는 프로그램 수',status='기획 합의',sources=['../replanning-2026-09.md'])
slide(7,'추천의 우선순위','ranking',45,'우선 사용자가 선택한 직무로 실제 모집 중인 프로그램을 앞에 둡니다. 같은 모집 상태에서는 원하는 경험의 적합도, 가까운 마감, 최근 모집 시작 순입니다. 특히 가장 원하는 경험을 우선하며, 제작·앱·팀협업을 원할 때 세 조건 전체가 맞는 프로그램을 부분 일치보다 먼저 보여줍니다. 부분 일치는 맞는 속성만 강조합니다. 수치 가중치와 일부 동률 규칙은 후속 설계입니다.',priority='선택 직무 모집 중 → 경험 적합도 → 마감 임박 → 최근 모집 시작',items=[['전체 일치 우선','희망: 제작 | 앱 · 팀협업\n일치: 앱을 팀으로 제작'],['부분 일치도 탐색','앱을 혼자 제작 / 웹을 팀으로 제작\n실제로 일치하는 속성만 강조']],footnote='명시한 최우선 경험을 우선 · 세부 점수와 행동 보정 폭은 미정',status='우선순위 합의 · 계산식 미정',sources=['../replanning-2026-09.md','../action-based-experience-tags-draft.md'])
slide(8,'검색 결과가 없어도 다음 선택 제공','sequence',40,'필터를 고를 때 결과 수를 보여줍니다. 결과가 없다면 새로운 조건을 임의로 넣는 대신 사용자가 이미 고른 조건 중 결과가 있는 부분 조합을 제안합니다. 예를 들어 백엔드와 앱 팀제작을 함께 찾을 수 없다면 경험 조건을 유지하는 조합을 제안할 수 있습니다. 사용자가 직접 제안을 선택해야 필터가 바뀌고, 해제된 조건과 되돌리기를 제공합니다. 실제 검색의 AND/OR 규칙을 적용해 결과가 존재하는 조합만 제시합니다.',steps=[['전체 조건: 결과 없음','예시: 백엔드 + 제작(앱·팀협업)'],['결과 있는 부분 조합 제안','예시: 제작(앱·팀협업) · 12개'],['선택하면 즉시 적용','백엔드 조건 해제 안내 + 되돌리기']],footnote='12개는 가상 예시 · 실제 집계는 프로그램 단위 · 선택 전 자동 변경 없음',status='기획 합의 · 가상 사례',sources=['../replanning-2026-09.md'])
slide(9,'준비가 필요한 활동도 저장','split',35,'지금 자격이 부족해도 사용자가 앞으로 준비하고 싶을 수 있습니다. 그래서 자격 부족만으로 프로그램을 제외하지 않고 부족한 조건을 보여주며 저장할 수 있게 합니다. 자격 확인에 필요한 정보는 그때 입력받고 다른 공고에도 재사용하며 수정할 수 있습니다. 스크랩은 다시 보기 위한 행동으로, 첫 버전에는 추천 가중치와 분리합니다. 별도의 이런 프로그램 더 추천 반응을 사용하고 취소할 수 있게 합니다.',columns=[{'title':'지원 조건 확인','lines':['부족한 자격을 카드에 표시','필요한 정보만 그때 입력','입력 정보 재사용·수정']},{'title':'저장과 추천 반응 분리','lines':['스크랩: 나중에 다시 보기','더 추천: 추천 선호 신호','추천 반응은 취소 가능']}],footnote='자격 미충족만으로 자동 제외하지 않음 · 스크랩은 초기 학습 가중치에 미반영',status='기획 합의',sources=['../replanning-2026-09.md'])
slide(10,'원문과 회차를 기준으로 정보 관리','sequence',40,'수집 가능한 공개 모집 페이지부터 시작하고 개별 단체 홈페이지까지 출처를 확장합니다. SNS는 가능한 연결 방식과 제보, 수동 검토로 보완합니다. 태그에는 활동 내용의 근거를 보존하고 불확실한 후보는 관리자 검토 대기로 둡니다. 승인 전에는 검색이나 추천, 결과 수에 반영하지 않습니다. 지난 기수의 경험도 이번에 제공된다는 근거가 없으면 현재 추천에 섞지 않습니다.',steps=[['공개 모집 페이지 수집','공고사이트 + 개별 단체·기관 홈페이지'],['활동 내용과 근거 정리','불확실한 후보 태그는 관리자 검토'],['회차에 맞는 정보 제공','과거 경험은 지난 기수·이번 미확인으로 구분']],footnote='최초 출처·갱신 주기·중복 통합의 세부 기준은 미정',status='운영 방향 합의 · 세부 기준 미정',sources=['../replanning-2026-09.md','../initial-sources-and-ingestion-draft.md'])
slide(11,'현재 구현과 앞으로 만들 기능','split',35,'현재 네이티브 앱에는 샘플 기반 공고 탐색과 저장, 상세, 지도와 일정, 개인 일정 겹침 기능이 있습니다. iOS는 SwiftUI, Android는 Compose입니다. 이번 발표의 자동 수집, 구조화된 경험 태그, 개인화 추천과 조건 조합 제안은 새 기획이며 구현 완료 기능으로 말하지 않습니다. 프로그램 카드로의 전환 등 변경 범위는 구현 전에 플랫폼 담당과 조율해야 합니다.',columns=[{'title':'기존 앱에 구현','lines':['SwiftUI · Compose 네이티브 앱','샘플 공고 탐색·저장·상세','지도·일정·개인 일정 겹침']},{'title':'이번 재기획의 구현 과제','lines':['자동 수집과 경험 태그 검토','프로그램 중심 맞춤 추천','필터 개수와 부분 조합 제안']}],footnote='기존 구현은 역할 문서 기준 · 이번 발표 제작에서 앱 실행·빌드를 재검증하지 않음',status='기존 구현 / 새 기획 구분',sources=['../../context/product-planning-and-github-issues.md','../iteration-01.md'])
slide(12,'검증할 핵심 질문','closing',30,'Dearby가 검증하려는 가치는 원하는 직무와 경험을 선택하면 참여를 검토할 만한 활동을 빠르게 찾을 수 있느냐입니다. 후속 검증에서는 원하는 활동을 찾는 시간과 성공 여부, 추천 이유를 이해하는지 확인하려 합니다. 이 측정 방법은 제안이며 목표 수치와 실험 규모는 아직 정하지 않았습니다. 기획의 큰 방향은 합의됐고 이제 수집 규칙과 추천 세부 정책을 구체화해야 합니다.',headline='원하는 경험을 기준으로,\n참여할 활동을 더 쉽게 찾는가',items=[['평가 방법 제안','탐색 시간 · 참여 검토 후보 발견 여부\n추천 이유의 이해 여부'],['다음 결정','초기 수집 출처·갱신 기준\n추천 세부 규칙·기술 구성·목표 수치']],footnote='효과 수치는 아직 측정하지 않음 · 세부 기획 명세 작성 중',status='목표 합의 · 평가 방법 제안',sources=['../replanning-2026-09.md'])
slide(13,'부록: 검색과 태그 선택 규칙','table',0,'방향은 기본 OR이며 사용자가 모두 포함을 명시하면 AND로 바꿀 수 있습니다. 경험도 기본 OR이지만 방향 범주와 경험 범주는 함께 충족합니다. 하위 태그를 선택하면 상위 행위가 포함된 복합 조건 하나가 됩니다. 상위 전체를 독립 OR 조건으로 자동 추가하면 검색 범위가 넓어져 의도와 달라집니다. 결과 없음 제안은 실제 논리에 따라 결과가 생기는 부분 조합이어야 합니다.',headers=['선택','검색 의미'],rows=[['방향 여러 개','기본 하나라도 일치 · 모두 포함 선택 가능'],['경험 여러 개','하나라도 일치 · 더 적합한 경험 우선 노출'],['방향 + 경험','두 범주를 함께 충족'],['하위 태그 선택','상위+하위를 하나의 조건으로 선택'],['상위 전체 선택','해당 행위의 하위 유형을 포함']],footnote='예: 과제수행 | 서비스 기획 선택 ≠ 과제수행 전체 선택',status='기획 합의',sources=['../replanning-2026-09.md','../action-based-experience-tags-draft.md'])
slide(14,'부록: 기술 구성 검토','table',0,'초기에는 ELK 활용을 희망했고 구성별 역할을 검토했습니다. Elasticsearch는 검색과 조건별 집계, Logstash는 데이터 변환과 전달, Kibana는 운영 현황 확인이라는 방향입니다. 이후 PostgreSQL로 대체하거나 병행할 가능성을 검토했으며 최종 구성은 아직 정하지 않았습니다. ELK가 수집기나 추천 알고리즘을 자동으로 완성해 주는 것은 아닙니다. 이 표는 성능 검증 결과나 확정 아키텍처가 아닙니다.',headers=['후보','검토한 역할'],rows=[['Elasticsearch','활동 검색 · 조건별 결과 수 집계'],['Logstash','수집 데이터 변환 · 전달'],['Kibana','수집 실패 · 검색 결과 없음 등 운영 확인'],['PostgreSQL','원본 데이터 저장 · 구조화된 필터 대안 검토']],footnote='최종 채택·병행 여부 미정 · 수집기와 추천 알고리즘은 별도 설계',status='기술 검토 · 미결정',sources=['../replanning-2026-09.md'])
slide(15,'부록: 남은 결정과 검증','split',0,'합의한 내용과 남은 일을 구분하기 위한 부록입니다. 전체 사전, 출처 운영, 추천 세부 가중치, 사용자 정보 저장과 보관, 정량 성공 기준은 추가 결정이 필요합니다. 최초 수집 후보와 실제 태그 검토 예시는 기존 문서에 있으나 승인된 운영 데이터가 아닙니다. 학교 발표에서 완료 범위를 질문받으면 제품 방향과 핵심 탐색 규칙은 합의했고 구현과 실험은 남아 있다고 설명하면 됩니다.',columns=[{'title':'기획을 더 정할 항목','lines':['초기 출처·갱신·중복 기준','태그 전체 사전·동시 회차 조건','추천 가중치·조합 정렬·개수','사용자 정보 저장·보관 정책']},{'title':'실제로 검증할 항목','lines':['출처별 수집 가능성과 추출 품질','추천 및 태그의 정확성','탐색 성공 기준과 목표 수치','플랫폼별 기능 변경 범위']}],footnote='기획 합의가 구현 완료나 사용자 검증 완료를 뜻하지 않음',status='미완료 명세',sources=['../replanning-2026-09.md','../initial-sources-and-ingestion-draft.md'])
